<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientAuthorizationSignedResponseAlgAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientAuthorizationSignedResponseAlgAccessor trait.
 *
 * Covers null default, string/VO assignment via withAuthorizationSignedResponseAlg,
 * getAuthorizationSignedResponseAlg/authorizationSignedResponseAlg accessors, and isAuthorizationSignedResponseAlgChanged with/without original.
 */
class TrustedClientAuthorizationSignedResponseAlgAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withAuthorizationSignedResponseAlg creates a new instance with the AuthorizationSignedResponseAlg set
     * from a string value, and getAuthorizationSignedResponseAlg returns the primitive string.
     */
    public function testWithAuthorizationSignedResponseAlgFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAuthorizationSignedResponseAlgAccessorUnitTest();

        // Act
        $result = $holder->withAuthorizationSignedResponseAlg('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getAuthorizationSignedResponseAlg());
    }
    /**
     * Asserts that withauthorizationSignedResponseAlg has access to the value object
     * from a string value, and getAuthorizationSignedResponseAlg returns the primitive string.
     */
    public function testWithAuthorizationSignedResponseAlgFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAuthorizationSignedResponseAlgAccessorUnitTest();

        // Act
        $result = $holder->withAuthorizationSignedResponseAlg('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->authorizationSignedResponseAlg()->value());
    }
    public function testChangedAuthorizationSignedResponseAlg(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAuthorizationSignedResponseAlgAccessorUnitTest();
        $original = $holder->withAuthorizationSignedResponseAlg('one');
        $same = $holder->withAuthorizationSignedResponseAlg('one');
        $modified = $holder->withAuthorizationSignedResponseAlg('other');

        // Act
        $unchanged = $holder->isAuthorizationSignedResponseAlgChanged();
        $withSame = $original->isAuthorizationSignedResponseAlgChanged($same);
        $withDiferent = $original->isAuthorizationSignedResponseAlgChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientAuthorizationSignedResponseAlgAccessorUnitTest
{
    use TrustedClientAuthorizationSignedResponseAlgAccessor;
}
